/** Index par id, construit une seule fois. */
export const ICON_BY_ID: ReadonlyMap<string, GameIcon> = new Map(
  ICONS.map((icon) => [icon.id, icon]),
);

export function getIcon(id: string): GameIcon | undefined {
  return ICON_BY_ID.get(id);
}

/** Icônes regroupées par catégorie — utilisé par `dealHand` pour les quotas. */
export const ICONS_BY_CATEGORY: Readonly<Record<IconCategory, GameIcon[]>> =
  ICONS.reduce(
    (acc, icon) => {
      acc[icon.category].push(icon);
      return acc;
    },
    {
      objet: [],
      animal: [],
      nourriture: [],
      lieu: [],
      symbole: [],
      action: [],
      nature: [],
      personne: [],
    } as Record<IconCategory, GameIcon[]>,
  );
